import ifcopenshell
import ifcopenshell.geom
import numpy as np

f = ifcopenshell.open('/tmp/test_model.ifc')
print('Schema:', f.schema)

# Count elements
products = f.by_type('IfcProduct')
print(f'Total IfcProducts: {len(products)}')

by_class = {}
for p in products:
    cls = p.is_a()
    by_class[cls] = by_class.get(cls, 0) + 1

for k, v in sorted(by_class.items()):
    print(f'  {k}: {v}')

# Verify geometry conversion with ifcopenshell.geom
settings = ifcopenshell.geom.settings()
settings.set(settings.USE_WORLD_COORDS, True)

shapes = {}
errors = []
for p in products:
    if p.Representation:
        try:
            shape = ifcopenshell.geom.create_shape(settings, p)
            shapes[p] = shape
        except Exception as e:
            errors.append((p.Name or p.GlobalId, str(e)))

print(f'Successfully meshed {len(shapes)} products.')
if errors:
    print(f'Mesh errors: {len(errors)}')
    for err in errors[:5]:
        print(' ', err)
else:
    print('ALL PRODUCTS MESHED WITH ZERO GEOMETRY ERRORS!')
"
